schema:
CREATE TABLE singer (singer_id INT, name TEXT, country TEXT, song_name TEXT, song_release_year TEXT, age INT, is_male BOOLEAN);
CREATE TABLE concert (concert_id INT, concert_name TEXT, theme TEXT, stadium_id INT, year INT);
CREATE TABLE singer_in_concert (concert_id INT, singer_id INT);

CREATE TABLE customers (customer_id INT PRIMARY KEY, first_name TEXT, last_name TEXT, email TEXT, country TEXT);
CREATE TABLE orders (order_id INT PRIMARY KEY, customer_id INT, order_date DATE, total_amount DECIMAL, status TEXT);
CREATE TABLE order_items (item_id INT PRIMARY KEY, order_id INT, product_id INT, quantity INT, unit_price DECIMAL);
